#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int loi = 0;
    for (int i = 0; i < n; i++) {
        int x;
        scanf("%d", &x);
        if (x == 0) loi++;
    }
    if (loi == 0) printf("tat ca dat\n");
    else printf("con loi: %d\n", loi);
    return 0;
}
